def col_shift_up(grid):
    """Shift each column UP by 1 (last element to top)"""
    rows = len(grid)
    cols = len(grid[0])
    result = [[0]*cols for _ in range(rows)]
    for c in range(cols):
        for r in range(1, rows):
            result[r][c] = grid[r-1][c]
        result[0][c] = grid[rows-1][c]
    return result

